import{api,identity,type Env}from'./api';
// The build embeds the existing Vite output, preserving the app and offline assets.
// @ts-ignore Generated by the deployment build.
import{assets}from'paperclub:assets';
const types:Record<string,string>={html:'text/html; charset=utf-8',js:'text/javascript; charset=utf-8',css:'text/css; charset=utf-8',svg:'image/svg+xml',webmanifest:'application/manifest+json',ttf:'font/ttf',txt:'text/plain; charset=utf-8',json:'application/json'};
export default{async fetch(request:Request,env:Env){const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return api(request,{...env,authenticate:async()=>identity(request),provider:'chatgpt'});
 if(request.method!=='GET'&&request.method!=='HEAD')return new Response('Method not allowed',{status:405});
 let path;try{path=decodeURIComponent(url.pathname)}catch{return new Response('Bad path',{status:400})}if(path==='/'||path==='/index.html')path='/index.html';
 let file=assets[path];if(!file&&!path.split('/').at(-1)?.includes('.')){path='/index.html';file=assets[path]}if(!file)return new Response('Not found',{status:404});
 const bytes=Uint8Array.from(atob(file),c=>c.charCodeAt(0));const extension=path.split('.').at(-1)||'';return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':types[extension]||'application/octet-stream','Cache-Control':path.startsWith('/assets/')?'public, max-age=31536000, immutable':'public, max-age=0, must-revalidate','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; base-uri 'self'; form-action 'self'"}})
}};
